/**
 * Supabase Client Mocks
 *
 * Provides mock Supabase clients for testing components that interact
 * with the database. Includes configurable query builders and auth mocks.
 *
 * Usage:
 *   import { createMockSupabaseClient } from '@/__tests__/mocks/supabase'
 *
 *   test('fetches data', async () => {
 *     const mockClient = createMockSupabaseClient({
 *       selectData: [{ id: '1', name: 'Test' }]
 *     })
 *     // Use mockClient in your test
 *   })
 */

import { vi } from 'vitest'
import type { User, Session } from '@supabase/supabase-js'

/**
 * Mock user for Supabase auth
 */
export const MOCK_USER: User = {
  id: 'test-user-id',
  email: 'test@example.com',
  aud: 'authenticated',
  role: 'authenticated',
  created_at: '2024-01-01T00:00:00Z',
  app_metadata: {},
  user_metadata: {},
  updated_at: '2024-01-01T00:00:00Z',
}

/**
 * Mock session for Supabase auth
 */
export const MOCK_SESSION: Session = {
  access_token: 'mock-access-token',
  refresh_token: 'mock-refresh-token',
  expires_in: 3600,
  expires_at: Math.floor(Date.now() / 1000) + 3600,
  token_type: 'bearer',
  user: MOCK_USER,
}

/**
 * Configuration options for mock query builder
 */
export interface MockQueryBuilderConfig {
  /** Data to return for select queries */
  selectData?: unknown | unknown[] | null
  /** Data to return for insert operations */
  insertData?: unknown | null
  /** Data to return for update operations */
  updateData?: unknown | null
  /** Data to return for delete operations */
  deleteData?: unknown | null
  /** Error to return for select queries */
  selectError?: { message: string } | null
  /** Error to return for insert operations */
  insertError?: { message: string } | null
  /** Error to return for update operations */
  updateError?: { message: string } | null
  /** Error to return for delete operations */
  deleteError?: { message: string } | null
  /** Total count for paginated queries */
  count?: number | null
}

/**
 * Configuration options for mock Supabase client
 */
export interface MockSupabaseClientConfig extends MockQueryBuilderConfig {
  /** Whether the user is authenticated */
  isAuthenticated?: boolean
  /** Custom user object */
  user?: User | null
  /** Custom session object */
  session?: Session | null
  /** Error for auth operations */
  authError?: { message: string } | null
}

/**
 * Create a mock query builder for Supabase queries
 *
 * @param config - Configuration for the mock query builder
 * @returns A mock query builder object
 */
export function createMockQueryBuilder(config: MockQueryBuilderConfig = {}) {
  let isInsertOperation = false
  let isUpdateOperation = false
  let isDeleteOperation = false

  const queryBuilder = {
    select: vi.fn(() => queryBuilder),
    insert: vi.fn(() => {
      isInsertOperation = true
      return queryBuilder
    }),
    update: vi.fn(() => {
      isUpdateOperation = true
      return queryBuilder
    }),
    delete: vi.fn(() => {
      isDeleteOperation = true
      return queryBuilder
    }),
    upsert: vi.fn(() => queryBuilder),
    eq: vi.fn(() => queryBuilder),
    neq: vi.fn(() => queryBuilder),
    gt: vi.fn(() => queryBuilder),
    gte: vi.fn(() => queryBuilder),
    lt: vi.fn(() => queryBuilder),
    lte: vi.fn(() => queryBuilder),
    like: vi.fn(() => queryBuilder),
    ilike: vi.fn(() => queryBuilder),
    in: vi.fn(() => queryBuilder),
    is: vi.fn(() => queryBuilder),
    not: vi.fn(() => queryBuilder),
    or: vi.fn(() => queryBuilder),
    and: vi.fn(() => queryBuilder),
    order: vi.fn(() => queryBuilder),
    limit: vi.fn(() => queryBuilder),
    range: vi.fn(() => queryBuilder),
    single: vi.fn(() => {
      if (isInsertOperation) {
        return Promise.resolve({
          data: config.insertError ? null : config.insertData,
          error: config.insertError ?? null,
        })
      }
      if (isUpdateOperation) {
        return Promise.resolve({
          data: config.updateError ? null : config.updateData,
          error: config.updateError ?? null,
        })
      }
      if (isDeleteOperation) {
        return Promise.resolve({
          data: config.deleteError ? null : config.deleteData,
          error: config.deleteError ?? null,
        })
      }
      return Promise.resolve({
        data: config.selectData,
        error: config.selectError ?? null,
      })
    }),
    maybeSingle: vi.fn(() => {
      return Promise.resolve({
        data: config.selectData ?? null,
        error: config.selectError ?? null,
      })
    }),
    then: vi.fn((callback) => {
      if (isInsertOperation) {
        const result = {
          data: config.insertError ? null : config.insertData,
          error: config.insertError ?? null,
        }
        return Promise.resolve(result).then(callback)
      }
      if (isUpdateOperation) {
        const result = {
          data: config.updateError ? null : config.updateData,
          error: config.updateError ?? null,
        }
        return Promise.resolve(result).then(callback)
      }
      if (isDeleteOperation) {
        const result = {
          data: config.deleteError ? null : config.deleteData,
          error: config.deleteError ?? null,
        }
        return Promise.resolve(result).then(callback)
      }
      return Promise.resolve({
        data: Array.isArray(config.selectData) ? config.selectData : null,
        error: config.selectError ?? null,
        count: config.count ?? null,
      }).then(callback)
    }),
  }

  return queryBuilder
}

/**
 * Create a mock Supabase client for testing
 *
 * @param config - Configuration for the mock client
 * @returns A mock Supabase client
 *
 * @example
 * const mockClient = createMockSupabaseClient({
 *   selectData: [{ id: '1', name: 'Product 1' }],
 *   isAuthenticated: true
 * })
 */
export function createMockSupabaseClient(config: MockSupabaseClientConfig = {}) {
  const {
    isAuthenticated = true,
    user = isAuthenticated ? MOCK_USER : null,
    session = isAuthenticated ? MOCK_SESSION : null,
    authError = null,
    ...queryBuilderConfig
  } = config

  const queryBuilder = createMockQueryBuilder(queryBuilderConfig)
  const fromFn = vi.fn(() => queryBuilder)

  return {
    from: fromFn,
    auth: {
      getUser: vi.fn(() =>
        Promise.resolve({
          data: { user },
          error: authError,
        })
      ),
      getSession: vi.fn(() =>
        Promise.resolve({
          data: { session },
          error: authError,
        })
      ),
      signInWithPassword: vi.fn(({ email }: { email: string; password: string }) =>
        Promise.resolve({
          data: {
            user: authError ? null : { ...MOCK_USER, email },
            session: authError ? null : MOCK_SESSION,
          },
          error: authError,
        })
      ),
      signUp: vi.fn(() =>
        Promise.resolve({
          data: { user, session: null },
          error: authError,
        })
      ),
      signOut: vi.fn(() =>
        Promise.resolve({
          error: authError,
        })
      ),
      onAuthStateChange: vi.fn((callback) => {
        // Optionally trigger callback immediately
        if (isAuthenticated) {
          callback('SIGNED_IN', session)
        }
        return {
          data: {
            subscription: {
              unsubscribe: vi.fn(),
            },
          },
        }
      }),
    },
    // Expose internal state for testing
    _getQueryBuilder: () => queryBuilder,
  }
}

/**
 * Create a mock Supabase client that simulates an authentication error
 *
 * @param errorMessage - The error message to return
 * @returns A mock Supabase client configured with auth error
 */
export function createMockSupabaseClientWithAuthError(
  errorMessage = 'Authentication failed'
) {
  return createMockSupabaseClient({
    isAuthenticated: false,
    authError: { message: errorMessage },
  })
}

/**
 * Create a mock Supabase client that simulates a database error
 *
 * @param errorMessage - The error message to return
 * @returns A mock Supabase client configured with database error
 */
export function createMockSupabaseClientWithDbError(errorMessage = 'Database error') {
  return createMockSupabaseClient({
    selectError: { message: errorMessage },
    insertError: { message: errorMessage },
    updateError: { message: errorMessage },
    deleteError: { message: errorMessage },
  })
}
